CREATE TABLE "stores" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "uuid" TEXT NULL, "name" TEXT NOT NULL UNIQUE, "address" TEXT NULL, "receipt_template" TEXT NULL, "is_active" INTEGER NOT NULL DEFAULT 1 CHECK ("is_active" IN (0, 1)), "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)));
CREATE TABLE "users" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "uuid" TEXT NULL, "username" TEXT NOT NULL UNIQUE, "full_name" TEXT NOT NULL, "password_hash" TEXT NOT NULL, "role" TEXT NOT NULL, "store_id" INTEGER NULL REFERENCES stores (id), "is_active" INTEGER NOT NULL DEFAULT 1 CHECK ("is_active" IN (0, 1)), "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "last_login_at" INTEGER NULL, "seal" TEXT NULL);
CREATE TABLE "categories" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "uuid" TEXT NULL, "name" TEXT NOT NULL UNIQUE);
CREATE TABLE "units" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "uuid" TEXT NULL, "name" TEXT NOT NULL UNIQUE);
CREATE TABLE "products" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "uuid" TEXT NULL, "code" TEXT NOT NULL UNIQUE, "barcode" TEXT NULL UNIQUE, "name" TEXT NOT NULL, "category_id" INTEGER NULL REFERENCES categories (id), "unit_id" INTEGER NULL REFERENCES units (id), "purchase_price" INTEGER NOT NULL DEFAULT 0, "selling_price" INTEGER NOT NULL DEFAULT 0, "stock" REAL NOT NULL DEFAULT 0.0, "min_stock" REAL NOT NULL DEFAULT 0.0, "is_active" INTEGER NOT NULL DEFAULT 1 CHECK ("is_active" IN (0, 1)), "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "updated_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "seal" TEXT NULL);
CREATE TABLE "vouchers" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "uuid" TEXT NULL, "code" TEXT NOT NULL UNIQUE, "name" TEXT NOT NULL DEFAULT '', "type" TEXT NOT NULL, "value" REAL NOT NULL, "max_discount" INTEGER NULL, "min_purchase" INTEGER NOT NULL DEFAULT 0, "start_date" INTEGER NULL, "end_date" INTEGER NULL, "store_id" INTEGER NULL REFERENCES stores (id), "is_active" INTEGER NOT NULL DEFAULT 1 CHECK ("is_active" IN (0, 1)), "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)));
CREATE TABLE "payment_methods" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "uuid" TEXT NULL, "name" TEXT NOT NULL UNIQUE, "kind" TEXT NOT NULL, "is_active" INTEGER NOT NULL DEFAULT 1 CHECK ("is_active" IN (0, 1)), "sort_order" INTEGER NOT NULL DEFAULT 0, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)));
CREATE TABLE "sales" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "uuid" TEXT NULL, "invoice_no" TEXT NOT NULL UNIQUE, "terminal_code" TEXT NULL, "store_id" INTEGER NULL REFERENCES stores (id), "sale_date" INTEGER NOT NULL, "user_id" INTEGER NOT NULL REFERENCES users (id), "item_count" INTEGER NOT NULL, "subtotal" INTEGER NOT NULL, "discount_percent" REAL NULL, "discount" INTEGER NOT NULL DEFAULT 0, "voucher_id" INTEGER NULL REFERENCES vouchers (id), "voucher_code" TEXT NULL, "total" INTEGER NOT NULL, "paid" INTEGER NOT NULL, "change_amount" INTEGER NOT NULL, "payment_method" TEXT NOT NULL DEFAULT 'tunai', "payment_method_id" INTEGER NULL REFERENCES payment_methods (id), "payment_ref" TEXT NULL, "return_of_id" INTEGER NULL REFERENCES sales (id), "return_reason" TEXT NULL, "exchange_of_id" INTEGER NULL REFERENCES sales (id) ON DELETE SET NULL, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)));
CREATE TABLE "sale_items" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "uuid" TEXT NULL, "sale_id" INTEGER NOT NULL REFERENCES sales (id) ON DELETE CASCADE, "product_id" INTEGER NOT NULL REFERENCES products (id), "product_code" TEXT NOT NULL, "product_name" TEXT NOT NULL, "unit_name" TEXT NULL, "qty" REAL NOT NULL, "price" INTEGER NOT NULL, "discount_percent" REAL NOT NULL DEFAULT 0.0, "purchase_price" INTEGER NOT NULL, "subtotal" INTEGER NOT NULL, "return_of_item_id" INTEGER NULL);
CREATE TABLE "stock_movements" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "uuid" TEXT NULL, "product_id" INTEGER NOT NULL REFERENCES products (id), "store_id" INTEGER NULL REFERENCES stores (id), "user_id" INTEGER NULL REFERENCES users (id), "type" TEXT NOT NULL, "qty_change" REAL NOT NULL, "ref_id" INTEGER NULL, "note" TEXT NULL, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)));
CREATE TABLE "settings" ("key" TEXT NOT NULL, "value" TEXT NOT NULL, PRIMARY KEY ("key"));
CREATE TABLE "sync_outbox" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "entity" TEXT NOT NULL, "entity_uuid" TEXT NOT NULL, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "attempts" INTEGER NOT NULL DEFAULT 0, "last_attempt_at" INTEGER NULL, "last_error" TEXT NULL, "sent_at" INTEGER NULL);
CREATE TABLE "held_carts" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" INTEGER NOT NULL REFERENCES users (id), "store_id" INTEGER NULL REFERENCES stores (id), "note" TEXT NULL, "items" TEXT NOT NULL, "item_count" INTEGER NOT NULL, "total" INTEGER NOT NULL, "created_at" INTEGER NOT NULL);
CREATE TABLE "store_products" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "uuid" TEXT NULL, "store_id" INTEGER NOT NULL REFERENCES stores (id), "product_id" INTEGER NOT NULL REFERENCES products (id) ON DELETE CASCADE, "stock" REAL NOT NULL DEFAULT 0.0, "selling_price" INTEGER NULL, "seal" TEXT NULL, UNIQUE ("store_id", "product_id"));
CREATE TABLE "tags" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "uuid" TEXT NULL, "name" TEXT NOT NULL UNIQUE, "color" TEXT NOT NULL DEFAULT 'blue', "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)));
CREATE TABLE "product_tags" ("product_id" INTEGER NOT NULL REFERENCES products (id) ON DELETE CASCADE, "tag_id" INTEGER NOT NULL REFERENCES tags (id) ON DELETE CASCADE, "uuid" TEXT NULL, PRIMARY KEY ("product_id", "tag_id"));
CREATE TABLE "audit_log" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "uuid" TEXT NULL, "created_at" INTEGER NOT NULL, "user_id" INTEGER NULL, "user_name" TEXT NULL, "store_id" INTEGER NULL, "terminal_code" TEXT NULL, "type" TEXT NOT NULL, "summary" TEXT NOT NULL, "data" TEXT NULL, "prev_hash" TEXT NOT NULL, "hash" TEXT NOT NULL);
CREATE TABLE "role_permissions" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "uuid" TEXT NULL, "role" TEXT NOT NULL, "permission" TEXT NOT NULL, "seal" TEXT NULL, UNIQUE ("role", "permission"));
CREATE UNIQUE INDEX idx_users_uuid ON users (uuid);
CREATE UNIQUE INDEX idx_categories_uuid ON categories (uuid);
CREATE UNIQUE INDEX idx_units_uuid ON units (uuid);
CREATE INDEX idx_products_name ON products (name);
CREATE UNIQUE INDEX idx_products_uuid ON products (uuid);
CREATE UNIQUE INDEX idx_vouchers_uuid ON vouchers (uuid);
CREATE UNIQUE INDEX idx_payment_methods_uuid ON payment_methods (uuid);
CREATE INDEX idx_sales_date ON sales (sale_date);
CREATE UNIQUE INDEX idx_sales_uuid ON sales (uuid);
CREATE INDEX idx_sales_return_of ON sales (return_of_id);
CREATE UNIQUE INDEX idx_sale_items_uuid ON sale_items (uuid);
CREATE UNIQUE INDEX idx_stock_movements_uuid ON stock_movements (uuid);
CREATE INDEX idx_sync_outbox_pending ON sync_outbox (sent_at, id);
CREATE UNIQUE INDEX idx_stores_uuid ON stores (uuid);
CREATE UNIQUE INDEX idx_store_products_uuid ON store_products (uuid);
CREATE UNIQUE INDEX idx_tags_uuid ON tags (uuid);
CREATE UNIQUE INDEX idx_product_tags_uuid ON product_tags (uuid);
CREATE INDEX idx_product_tags_tag ON product_tags (tag_id);
CREATE INDEX idx_audit_log_created ON audit_log (created_at);
CREATE UNIQUE INDEX idx_role_permissions_uuid ON role_permissions (uuid);
